namespace StockManager.Voucher.Output
{
    public partial class frmItemInputHistory : FormBase, IForm
    {
        #region Variables

        private long lngItemID = 0;
        private int intStoreID = 0;
        private string strItemCode = "";
        private string strItemName = "";
        private DataTable dtbHistory = null;

        #endregion

        #region IForm Members

        private static frmItemInputHistory _instance = null;
        private static object lockObject = new object();

        public static frmItemInputHistory Instance
        {
            get
            {
                lock (lockObject)
                {
                    if (_instance == null)
                        _instance = new frmItemInputHistory();
                    return _instance;
                }
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmItemInputHistory()
        {
            InitializeComponent();
        }

        #region Support Functions

        /// <summary>
        /// Load dữ liệu lịch sử nhập của mặt hàng
        /// </summary>
        public void LoadData(long itemID, int storeID, string itemCode, string itemName)
        {
            lngItemID = itemID;
            intStoreID = storeID;
            strItemCode = itemCode;
            strItemName = itemName;

            // Hiển thị thông tin hàng
            lblItemInfo.Text = String.Format("Hàng: {0} - {1}", strItemCode, strItemName);

            SMS_OutputVoucherDetail objDetail = new SMS_OutputVoucherDetail();
            dtbHistory = objDetail.GetItemInputVoucherHistory(itemID, storeID);

            if (dtbHistory == null)
            {
                MessageManager.Error("Việc tải lịch sử nhập hàng bị lỗi!");
                return;
            }

            gcHistory.DataSource = dtbHistory;

            if (dtbHistory.Rows.Count > 0)
            {
                // Hiển thị giá bình quân từ dòng đầu tiên
                decimal decAvgCost = Convert.ToDecimal(dtbHistory.Rows[0]["AvgCostPrice"]);
                lblAvgCostPrice.Text = String.Format("Giá bình quân: {0:N0}", decAvgCost);
            }
            else
            {
                lblAvgCostPrice.Text = "Giá bình quân: 0";
            }

            ModifyGrid();
        }

        private void ModifyGrid()
        {
            if (gvHistory.Columns["InputVoucherDetailID"] != null)
            {
                gvHistory.Columns["InputVoucherDetailID"].Visible = false;
            }

            if (gvHistory.Columns["AvgCostPrice"] != null)
            {
                gvHistory.Columns["AvgCostPrice"].Visible = false;
            }

            if (gvHistory.Columns["InputVoucherCode"] != null)
            {
                gvHistory.Columns["InputVoucherCode"].Caption = "Số phiếu nhập";
                gvHistory.Columns["InputVoucherCode"].Width = 120;
            }

            if (gvHistory.Columns["InputDate"] != null)
            {
                gvHistory.Columns["InputDate"].Caption = "Ngày nhập";
                gvHistory.Columns["InputDate"].Width = 100;
                gvHistory.Columns["InputDate"].DisplayFormat.FormatType = DevExpress.Utils.FormatType.DateTime;
                gvHistory.Columns["InputDate"].DisplayFormat.FormatString = "dd/MM/yyyy";
            }

            if (gvHistory.Columns["InputQuantity"] != null)
            {
                gvHistory.Columns["InputQuantity"].Caption = "SL nhập";
                gvHistory.Columns["InputQuantity"].Width = 90;
                gvHistory.Columns["InputQuantity"].DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
                gvHistory.Columns["InputQuantity"].DisplayFormat.FormatString = "N0";
            }

            if (gvHistory.Columns["CostPrice"] != null)
            {
                gvHistory.Columns["CostPrice"].Caption = "Giá nhập";
                gvHistory.Columns["CostPrice"].Width = 100;
                gvHistory.Columns["CostPrice"].DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
                gvHistory.Columns["CostPrice"].DisplayFormat.FormatString = "N0";
                gvHistory.Columns["CostPrice"].AppearanceCell.BackColor = Color.LightYellow;
                gvHistory.Columns["CostPrice"].AppearanceCell.Options.UseBackColor = true;
            }

            if (gvHistory.Columns["Remaining"] != null)
            {
                gvHistory.Columns["Remaining"].Caption = "Tồn còn";
                gvHistory.Columns["Remaining"].Width = 90;
                gvHistory.Columns["Remaining"].DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
                gvHistory.Columns["Remaining"].DisplayFormat.FormatString = "N0";
            }
        }

        #endregion

        #region Form Actions

        private void frmItemInputHistory_Load(object sender, EventArgs e)
        {
            SetToolTip();
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void frmItemInputHistory_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;

                case Keys.Escape:
                    btnClose_Click(sender, null);
                    break;
            }
        }

        #endregion
    }
}

