private System.Windows.Forms.ToolStripMenuItem mnuItemSetOrderIndex;
private System.Windows.Forms.ToolStripMenuItem mnuItemCheckItem;
private System.Windows.Forms.ToolStripSeparator toolStripSeparator2;

    private void mnuItemSetOrderIndex_Click(object sender, EventArgs e)
    {
        if (dtbData != null)
        {
            for (int i = 0; i < gvData.RowCount; i++)
            {
                DataRow drw = gvData.GetDataRow(i);
                drw["OrderIndex"] = i + 1;
                drw["IsEdit"] = 1;
            }
        }
    }

    private void mnuItemCheckItem_Click(object sender, EventArgs e)
    {
        if (gvData.FocusedRowHandle < 0)
        {
            MessageManager.Warning("Vui lòng chọn một dòng hàng hóa để kiểm tra!");
            return;
        }

        DataRow drw = gvData.GetDataRow(gvData.FocusedRowHandle);
        if (drw == null)
        {
            MessageManager.Warning("Không có dữ liệu dòng được chọn!");
            return;
        }

        if (drw["ItemID"].ToString() == "")
        {
            MessageManager.Warning("Dòng chưa có mã hàng!");
            return;
        }

        if (uStore.StoreID == null)
        {
            MessageManager.Warning("Vui lòng chọn kho trước khi kiểm tra hàng!");
            return;
        }

        long lngItemID = Convert.ToInt64(drw["ItemID"]);
        int intStoreID = Convert.ToInt32(uStore.StoreID);
        string strItemCode = drw["ItemCode"].ToString();
        string strItemName = drw["ItemName"].ToString();

        frmItemInputHistory frm = frmItemInputHistory.Instance;
        frm.LoadData(lngItemID, intStoreID, strItemCode, strItemName);
        frm.ShowDialog();
    }


}//class

